export const concepts:Concept[]=[
c("sensor","Sensors, Platforms & Orbits","Sensor","An instrument or device that makes the measurement.",3,["Examples: radiometer, spectrometer, sounder, interferometer, SAR, altimeter, LiDAR, scanner, spectroradiometer."],"easy"),
c("platform","Sensors, Platforms & Orbits","Platform","A vehicle that supports or carries the sensor.",4,["Examples include satellite, space shuttle, airplane, helicopter, balloon and ship."],"easy"),
c("categories","Sensors, Platforms & Orbits","Sensor categories","Sensors can be categorized by utilized electromagnetic spectrum and by illumination energy source.",6,["Spectrum: optical, microwave, infrared.","Energy: passive or active."],"medium"),
c("geo","Sensors, Platforms & Orbits","Geostationary/Geosynchronous orbit","An equatorial orbit synchronous with Earth's rotation, providing a constant view of part of Earth.",7,["Appears stationary relative to Earth's surface.","Examples: US GOES and Japan GMS."],"medium"),
c("polar","Sensors, Platforms & Orbits","Polar/Sun-synchronous orbit","An orbit moving around Earth's poles, generally inclined 8 to 10 degrees rather than true north-south.",8,["Passes over the same point after several days.","Examples: Landsat and SPOT."],"medium"),
c("framing","Imaging & Scanning Systems","Framing system","Instantaneously acquires an image of an area or frame on terrain.",12,["Examples: cameras and Vidicon television camera."],"easy"),
c("scanning","Imaging & Scanning Systems","Scanning system","Uses a narrow IFOV that sweeps terrain to build a two-dimensional surface image.",13,["Reflected radiance is optically scanned and electronically recorded."],"easy"),
c("whisk","Imaging & Scanning Systems","Across/Cross-track (Whiskbroom) scanning","Scans lines perpendicular to platform motion across the swath using a rotating mirror.",14,["Also called Whiskbroom Scanning."],"medium"),
c("push","Imaging & Scanning Systems","Along-track (Pushbroom) scanning","Uses forward platform motion and a linear detector array at the focal plane to record successive scan lines.",15,["Avoids a scanning mirror.","Advantages: increases sensor life and eliminates geometric errors from scan-mirror velocity variation."],"medium"),
c("circular","Imaging & Scanning Systems","Circular scanning","A vertical-axis scan motor and mirror sweeps a circular terrain path.",17,["Constant scanner-to-terrain distance.","Requires extensive reformatting before processing."],"hard"),
c("side","Imaging & Scanning Systems","Side scanning","A scanning mode primarily used by active remote sensing systems.",18,[],"easy"),
c("resolution","Digital Image Resolution","Resolution","Ability of an imaging system to record fine detail in a distinguishable manner.",21,["Detail is also affected by scene character, atmosphere, illumination and interpreter ability."],"easy"),
c("spatial","Digital Image Resolution","Spatial resolution","Fineness of spatial detail; the size of the smallest resolvable ground object.",22,["Limited by pixel size in a digital image.","High: 0.6-4 m; Medium: 4-30 m; Low: 30-1000 m."],"medium"),
c("spectral","Digital Image Resolution","Spectral resolution","Ability of a sensor to define fine wavelength intervals it can record.",24,["High: 220 bands; Medium: 3-15 bands; Low: 3 bands."],"medium"),
c("multiband","Digital Image Resolution","Multiband image types","Multispectral has a few layers at particular wavelength bands; superspectral has many more; hyperspectral has about 100 or more contiguous bands.",26,[],"hard"),
c("radiometric","Digital Image Resolution","Radiometric resolution","Ability of a sensor to record many brightness levels; the smallest detectable intensity change.",27,["Coarse resolution uses few levels/bits.","Landsat 8: 12 bit = 4096 levels."],"medium"),
c("temporal","Digital Image Resolution","Temporal resolution","The revisiting frequency of a satellite sensor for a specific location.",30,["High: <24 hours-3 days; Medium: 4-16 days; Low: >16 days.","Landsat 7/8: 16 days; SPOT 5: 2-3 days; IKONOS: 3 days at 40 latitude; QuickBird 1: 3.5 days."],"medium"),
c("mss","Landsat Systems","Landsat MSS","First Landsat generation instrument; Landsat was first launched in 1972.",32,["4 bands: green, red, NIR x2; 80 m ground resolution; 185 km swath.","Sun synchronous: 103 minutes, 14 orbits/day; repeat coverage 18 days (252 orbits)."],"hard"),
c("tm","Landsat Systems","Landsat Thematic Mapper","Upgraded Landsat 4 instrument launched in 1982.",33,["Seven bands: blue, green, red, NIR, SWIR x2, TIR.","30 m ground resolution, 185 km swath; Landsat 7 added 15 m panchromatic."],"hard"),
c("etm","Landsat Systems","Landsat 7 ETM+","Enhanced Thematic Mapper Plus is the main Landsat 7 instrument.",36,["15 m panchromatic; 60 m thermal infrared; 532 images/day capacity.","232 orbits/15 days; polar sun-synchronous."],"hard"),
c("slc","Landsat Systems","Scan Line Corrector (SLC)","Component behind primary optics that compensates long-track spacecraft motion during cross-track scan.",41,["Produces a rectilinear pattern instead of a zig-zag pattern."],"hard"),
c("l8","Landsat Systems","Landsat 8 capabilities","USGS assumed possession from NASA on 05/30/13; approximately 500 new scenes daily.",44,["8-10x signal-to-noise improvement, 12-bit quantization, coastal blue and cirrus bands, plus additional thermal band."],"hard"),
c("spot","SPOT & IRS","SPOT","Systeme Pour L’Observation De La Terre, a French satellite launched in 1986.",47,["First satellite system using linear array sensor and pointable optics.","Panchromatic/multispectral modes; off-nadir and stereo capability."],"medium"),
c("spot5","SPOT & IRS","SPOT 5","SPOT 5 launched May 3, 2002 from Kourou, French Guiana.",48,["822 km altitude; 98.7° sun-synchronous; 101.4-minute orbit; 2-3 day revisit.","Pan: 2.5 m from 2x5 m scenes/5 m nadir; MS: 10 m; SWIR: 20 m."],"expert"),
c("irs","SPOT & IRS","IRS satellites","Indian Remote Sensing satellite series includes IRS 1A, 1B and 1C.",56,["IRS 1A: 4 bands, 72 m, 148 km swath, 1988.","IRS 1B: 36 m, 1991. IRS 1C: 4 bands, 25-70 m, 141 km, 1996.","PAN: 5 m/70 km; WiFS: one band, 188 m, 774 km, 5-day revisit."],"expert"),
c("ikonos","Commercial High Resolution","IKONOS","Space Imaging commercial high-resolution satellite with Carterra instrument.",58,["Multispectral: 4 bands at 4 m; panchromatic: 1 m."],"medium"),
c("alos","Commercial High Resolution","ALOS Daichi","Advanced Land Observing Satellite.",69,["Sensors: PRISM stereo mapper, AVNIR 2 visible/NIR radiometer, PALSAR L-band SAR."],"medium"),
c("wv2","Commercial High Resolution","WorldView 2","WorldView 2 has panchromatic and 8 multispectral bands.",76,["Standard: blue, green, red, near IR 1; new: coastal, yellow, red edge, near IR 2.","Pan: 0.46 m nadir/0.52 m at 20° off-nadir; MS: 1.84 m nadir/2.08 m off-nadir."],"expert"),
c("wv3","Commercial High Resolution","WorldView 3","Very high-resolution satellite launched August 13, 2014.",81,["Panchromatic 31 cm; visible/NIR 1.24 m; SWIR 3.7 m."],"hard"),
c("avhrr","Environmental & Airborne Systems","NOAA-AVHRR","Advance Very High Resolution Radiometer weather satellite series launched in 1978.",93,["5 bands, 1.1 km resolution, 2700 km swath.","For economical global or continental scale monitoring; ocean temperature mapping."],"medium"),
c("resurs","Environmental & Airborne Systems","RESURS","Russian satellite marketed by Sweden.",95,["Five visible/NIR bands, 150 m resolution, 600 km swath."],"medium"),
c("topex","Environmental & Airborne Systems","TOPEX/Poseidon","French/USA oceanographic satellite with a radar altimeter.",97,["Measures wave height."],"easy"),
c("seawifs","Environmental & Airborne Systems","SeaWIFS","Sea Viewing Wide Field of View Sensor for oceanographic colour imaging.",98,["1 August 1997; 1.1 km; 2806 km swath; 8 visible/NIR bands; chlorophyll concentration."],"hard"),
c("modis","Environmental & Airborne Systems","EOS / MODIS","Earth Observation System includes MODIS on Terra (EOS-AM) and Aqua (EOS-PM).",100,["Terra crosses equator north-to-south in morning; Aqua south-to-north in afternoon.","Together view Earth every 1-2 days in 36 spectral bands."],"hard"),
c("airborne","Environmental & Airborne Systems","Airborne systems","Remote sensing systems carried by aircraft.",103,["Advantages: flexible timetable, altitude-controlled resolution, many bands.","Disadvantages: cost and operational complexity."],"medium")
];
